"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type KeyboardEvent, type PointerEvent, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a dial. Pass `value` to control it, or `defaultValue` to let it hold its own state. */
export type DialProps = Omit<ComponentPropsWithoutRef<"div">, "onChange" | "children" | "defaultValue"> & {
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  /** The dial snaps to multiples of this, counted from `min`. */
  step?: number;
  /** Formats the number in the middle and the `aria-valuetext`, for example to add a unit. */
  formatValue?: (value: number) => string;
  disabled?: boolean;
};

// The scale runs clockwise from the lower left to the lower right, with a gap at the bottom.
const START_ANGLE = -135;
const SWEEP = 270;
// A drag may not jump across the gap from one end of the scale to the other.
const MAX_DRAG_JUMP = 0.5;

// While the pointer drags, the mark follows it with no lag. A key press gets a
// short, critically damped spring so each step is visible.
const FOLLOW: Transition = { duration: 0 };
const STEP_SPRING: Transition = { type: "spring", stiffness: 700, damping: 53, mass: 1 };
const TICK: Transition = { duration: 0.16, ease: [0.165, 0.84, 0.44, 1] };
const ROLL: Transition = { duration: 0.18, ease: [0.165, 0.84, 0.44, 1] };
const ROLL_DISTANCE = 12;
const TICK_SCALE = 1.5;

const rollVariants = {
  enter: (direction: number) => ({ y: direction * ROLL_DISTANCE, opacity: 0 }),
  rest: { y: 0, opacity: 1 },
  exit: (direction: number) => ({ y: -direction * ROLL_DISTANCE, opacity: 0 }),
};

/**
 * Sets one number in a range by dragging around a ring or pressing arrow keys. The value snaps to steps, the
 * pointer mark ticks at each one, and the number in the middle rolls the way the value moved. Give it an
 * `aria-label` or `aria-labelledby`.
 */
export function Dial({
  value,
  defaultValue,
  onValueChange,
  min = 0,
  max = 100,
  step = 1,
  formatValue = String,
  disabled = false,
  className,
  onKeyDown,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  ...divProps
}: DialProps) {
  const [ownValue, setOwnValue] = useState(defaultValue ?? min);
  const [dragging, setDragging] = useState(false);
  // Counts the steps taken by hand. The mark is keyed by it, so each step replays the tick.
  const [ticks, setTicks] = useState(0);
  const [direction, setDirection] = useState(1);
  const reduceMotion = useReducedMotion();
  const current = Math.min(max, Math.max(min, value ?? ownValue));
  const fraction = max > min ? (current - min) / (max - min) : 0;
  const text = formatValue(current);

  const commit = (raw: number) => {
    const decimals = (String(step).split(".")[1] ?? "").length;
    const snapped = Number((min + Math.round((raw - min) / step) * step).toFixed(decimals));
    const next = Math.min(max, Math.max(min, snapped));
    if (next === current) return;
    if (value === undefined) setOwnValue(next);
    setDirection(next > current ? 1 : -1);
    setTicks((count) => count + 1);
    onValueChange?.(next);
  };

  const followPointer = (event: PointerEvent<HTMLDivElement>, allowJump: boolean) => {
    const box = event.currentTarget.getBoundingClientRect();
    const dx = event.clientX - (box.left + box.width / 2);
    const dy = event.clientY - (box.top + box.height / 2);
    if (dx === 0 && dy === 0) return;
    // Degrees clockwise from the top of the ring, from -180 to 180.
    const degrees = (Math.atan2(dx, -dy) * 180) / Math.PI;
    const pointed = Math.min(1, Math.max(0, (degrees - START_ANGLE) / SWEEP));
    if (!allowJump && Math.abs(pointed - fraction) > MAX_DRAG_JUMP) return;
    commit(min + pointed * (max - min));
  };

  const endDrag = (event: PointerEvent<HTMLDivElement>) => {
    if (event.currentTarget.hasPointerCapture?.(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    setDragging(false);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented || disabled) return;
    const moves = new Map([
      ["ArrowRight", current + step],
      ["ArrowUp", current + step],
      ["ArrowLeft", current - step],
      ["ArrowDown", current - step],
      ["PageUp", current + step * 10],
      ["PageDown", current - step * 10],
      ["Home", min],
      ["End", max],
    ]);
    const next = moves.get(event.key);
    if (next === undefined) return;
    event.preventDefault();
    commit(next);
  };

  return (
    <div
      {...divProps}
      role="slider"
      tabIndex={disabled ? -1 : 0}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuenow={current}
      aria-valuetext={text}
      aria-disabled={disabled || undefined}
      onKeyDown={handleKeyDown}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        if (event.defaultPrevented || disabled || event.button !== 0) return;
        event.currentTarget.setPointerCapture?.(event.pointerId);
        setDragging(true);
        followPointer(event, true);
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        if (dragging) followPointer(event, false);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        endDrag(event);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        endDrag(event);
      }}
      className={cn(
        // touch-none keeps a finger drag on the dial from scrolling the page.
        "relative flex size-40 shrink-0 cursor-grab touch-none select-none items-center justify-center rounded-full bg-card outline-none",
        "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        dragging && "cursor-grabbing",
        disabled && "cursor-not-allowed opacity-50",
        className,
      )}
    >
      {/* A circle starts at three o'clock, so the turn puts the start of the arc at the lower left. */}
      <svg viewBox="0 0 100 100" fill="none" aria-hidden="true" className="absolute inset-0 size-full rotate-135">
        <circle cx="50" cy="50" r="45" strokeWidth="5" pathLength={360} strokeDasharray={`${SWEEP} 360`} className="stroke-muted-foreground/25" />
        <circle cx="50" cy="50" r="45" strokeWidth="5" pathLength={360} strokeDasharray={`${fraction * SWEEP} 360`} className="stroke-primary" />
      </svg>
      <motion.div
        aria-hidden="true"
        initial={false}
        animate={{ rotate: START_ANGLE + fraction * SWEEP }}
        transition={reduceMotion || dragging ? FOLLOW : STEP_SPRING}
        className="absolute inset-0"
      >
        <motion.span
          key={ticks}
          initial={ticks > 0 && !reduceMotion ? { scale: TICK_SCALE } : false}
          animate={{ scale: 1 }}
          transition={TICK}
          className="absolute left-1/2 top-4 h-4 w-1 -translate-x-1/2 rounded-full bg-foreground"
        />
      </motion.div>
      {/* The slider role already reads the value out, so the visible number is hidden from assistive technology. */}
      <span aria-hidden="true" className="relative flex h-9 items-center overflow-hidden text-3xl font-semibold tabular-nums text-foreground">
        {reduceMotion ? (
          text
        ) : (
          <AnimatePresence mode="popLayout" initial={false} custom={direction}>
            <motion.span key={text} custom={direction} variants={rollVariants} initial="enter" animate="rest" exit="exit" transition={ROLL}>
              {text}
            </motion.span>
          </AnimatePresence>
        )}
      </span>
    </div>
  );
}
